{"success": true, "data": {"stdout": """"Norm sensitivity analysis: success rate vs correction norm bound.

Usage:
  python analysis/norm_sensitivity.py \
    --obs-only 0.05:logs/eval_obs_only_norm005.json 0.1:logs/eval_object_obs_only.json 0.2:logs/eval_obs_only_norm02.json \
    --perdof 0.1:logs/eval_object_perdof.json \
    --baselines vla_only:0.12 argmin:0.067 \
    --output analysis/results/norm_sensitivity.json
"""

import argparse
import ast
import json
import re
from pathlib import Path


def load_sr_from_json(path):
    with open(path) as f:
        data = json.load(f)
    return data["overall_success_rate"]


def load_sr_from_log(path):
    with open(path) as f:
        text = f.read()
    per_task = {}
    for m in re.finditer(
        r"^\[([^\]]+)\] success rate: [\d.]+% \((\d+)/(\d+)\)",
        text, re.MULTILINE,
    ):
        per_task[m.group(1)] = (int(m.group(2)), int(m.group(3)))
    if not per_task:
        return 0.0
    total_s = sum(v[0] for v in per_task.values())
    total_n = sum(v[1] for v in per_task.values())
    return total_s / total_n if total_n > 0 else 0.0


def load_sr(path):
    if path.endswith(".json"):
        return load_sr_from_json(path)
    return load_sr_from_log(path)


def parse_entries(entries):
    norms, rates = [], []
    for entry in entries:
        norm_str, path = entry.split(":", 1)
        norms.append(float(norm_str))
        rates.append(load_sr(path))
    order = sorted(range(len(norms)), key=lambda i: norms[i])
    return [norms[i] for i in order], [rates[i] for i in order]


def main():
    parser = argparse.ArgumentParser(description="Norm sensitivity analysis")
    parser.add_argument(
        "--obs-only",
        nargs="+",
        required=True,
        help="norm:path pairs for obs_only (e.g. 0.1:logs/eval_object_obs_only.json)",
    )
    parser.add_argument(
        "--perdof", nargs="+", default=[], help="norm:path pairs for perdof"
    )
    parser.add_argument(
        "--baselines",
        nargs="+",
        default=[],
        help="name:rate pairs for horizontal baselines (e.g. vla_only:0.12)",
    )
    parser.add_argument(
        "--output", default="analysis/results/norm_sensitivity.json"
    )
    args = parser.parse_args()

    result = {}

    obs_norms, obs_rates = parse_entries(args.obs_only)
    result["obs_only"] = {"norms": obs_norms, "success_rates": obs_rates}

    has_perdof = bool(args.perdof)
    per_norms, per_rates = [], []
    if has_perdof:
        per_norms, per_rates = parse_entries(args.perdof)
        result["perdof"] = {"norms": per_norms, "success_rates": per_rates}

    # Print table
    print(f"{'Norm':>8} {'obs_only':>10}", end="")
    if has_perdof:
        print(f" {'perdof':>10}", end="")
    print()
    print("-" * (20 + (12 if has_perdof else 0)))

    all_norms = sorted(set(obs_norms + per_norms))
    for norm in all_norms:
        print(f"{norm:>8.3f}", end="")
        if norm in obs_norms:
            idx = obs_norms.index(norm)
            print(f" {obs_rates[idx]*100:>9.1f}%", end="")
        else:
            print(f" {'n/a':>10}", end="")
        if has_perdof:
            if norm in per_norms:
                idx = per_norms.index(norm)
                print(f" {per_rates[idx]*100:>9.1f}%", end="")
            else:
                print(f" {'n/a':>10}", end="")
        print()

    baselines = {}
    for b in args.baselines:
        name, rate = b.split(":", 1)
        baselines[name] = float(rate)
    result["baselines"] = baselines

    if baselines:
        print()
        for name, rate in baselines.items():
            print(f"Baseline {name}: {rate*100:.1f}%")

    out_path = Path(args.output)
    out_path.parent.mkdir(parents=True, exist_ok=True)
    out_path.write_text(json.dumps(result, indent=2))
    print(f"\nSaved to {args.output}")


if __name__ == "__main__":
    main()
